SELECT * FROM material
WHERE id = #{materialId} AND owner_type = #{ownerType} AND owner_key = #{ownerKey}
  AND lifecycle_state IN ('ACTIVE', 'TRASHED')

SELECT material_id AS id, owner_key, retention_class, lifecycle_state,
       lifecycle_generation, expires_at, trash_expires_at
FROM material_lifecycle_request
WHERE owner_key = #{ownerKey} AND material_id = #{materialId}
  AND action = #{action} AND request_fingerprint = #{requestFingerprint}

SELECT material_id AS id, owner_key, retention_class, lifecycle_state,
       lifecycle_generation, expires_at, trash_expires_at
FROM material_lifecycle_request
WHERE owner_key = #{ownerKey} AND material_id = #{materialId}
  AND action = #{action} AND request_fingerprint = #{requestFingerprint}
FOR UPDATE

mapper.insert:
INSERT IGNORE INTO material_scope_link
    (id, material_id, scope_type, scope_key, created_by)
SELECT #{linkId}, id, #{scopeType}, #{scopeKey}, #{ownerKey}
FROM material
WHERE id = #{materialId} AND owner_type = #{ownerType} AND owner_key = #{ownerKey}
  AND lifecycle_state = 'ACTIVE'

mapper.update:
UPDATE material
SET retention_class = #{material.retentionClass},
    lifecycle_state = #{material.lifecycleState},
    lifecycle_generation = #{material.lifecycleGeneration},
    last_meaningful_activity_at = #{material.lastMeaningfulActivityAt},
    expires_at = #{material.expiresAt}, trash_expires_at = #{material.trashExpiresAt},
    deleted_at = #{material.deletedAt}
WHERE id = #{material.id} AND owner_type = #{material.ownerType}
  AND owner_key = #{material.ownerKey} AND lifecycle_generation = #{expectedGeneration}

mapper.select:
SELECT COUNT(*) FROM (
    SELECT conversation_id FROM conversation_source_context
    WHERE conversation_id = #{conversationId} AND owner_key = #{ownerKey}
    UNION
    SELECT session_id FROM diagram_conversation_message
    WHERE session_id = #{conversationId} AND user_id = #{ownerKey}
) owned_conversation

SELECT CONCAT(pin.version_id, ':', pin.processing_revision_id)
FROM diagram_source_pin pin WHERE pin.material_id = #{materialId}
UNION
SELECT CONCAT(ce.version_id, ':', ce.revision_id) FROM citation_evidence ce
JOIN material_version v ON v.id = ce.version_id WHERE v.material_id = #{materialId}
ORDER BY 1

SELECT * FROM material
WHERE retention_class = 'TEMPORARY' AND lifecycle_state = 'ACTIVE'
  AND expires_at <= #{now}
ORDER BY expires_at, id LIMIT #{limit}

SELECT * FROM material
WHERE lifecycle_state = 'TRASHED' AND trash_expires_at <= #{now}
ORDER BY trash_expires_at, id LIMIT #{limit}

SELECT * FROM material
WHERE owner_type = 'USER' AND owner_key = #{ownerKey}
  AND lifecycle_state IN ('ACTIVE', 'TRASHED')
ORDER BY id LIMIT #{limit}
